CREATE POLICY delegated_receipt_insert ON public.print_settings FOR INSERT TO authenticated WITH CHECK (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_print'));
CREATE POLICY delegated_receipt_update ON public.print_settings FOR UPDATE TO authenticated USING (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_print')) WITH CHECK (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_print'));
CREATE POLICY delegated_whatsapp_insert ON public.whatsapp_message_settings FOR INSERT TO authenticated WITH CHECK (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_whatsapp'));
CREATE POLICY delegated_whatsapp_update ON public.whatsapp_message_settings FOR UPDATE TO authenticated USING (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_whatsapp')) WITH CHECK (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_whatsapp'));
CREATE POLICY delegated_ota_manage ON public.ota_sources FOR ALL TO authenticated USING (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_ota')) WITH CHECK (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_ota'));
CREATE POLICY delegated_payment_methods_manage ON public.payment_methods FOR ALL TO authenticated USING (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_payment_methods')) WITH CHECK (public.has_store_access(auth.uid(),store_id) AND public.has_permission(auth.uid(),'settings_payment_methods'));
GRANT SELECT, INSERT, UPDATE ON public.print_settings, public.whatsapp_message_settings TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ota_sources, public.payment_methods TO authenticated;